package com.footballacademy.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*;
@Entity @Table(name="scouting_criterion_scores", indexes={@Index(name="idx_score_report", columnList="report_id"),@Index(name="idx_score_criterion", columnList="criterion_id")})
public class ScoutingCriterionScore { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="report_id") @JsonIgnore private ScoutingReport report; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="criterion_id") private ScoutingCriterion criterion; private Double score=0.0; @Column(length=1000) private String comment; public double weightedScore(){return (score==null?0:score)*(criterion==null||criterion.getWeight()==null?1:criterion.getWeight());} public Long getId(){return id;} public void setId(Long id){this.id=id;} public ScoutingReport getReport(){return report;} public void setReport(ScoutingReport report){this.report=report;} public ScoutingCriterion getCriterion(){return criterion;} public void setCriterion(ScoutingCriterion criterion){this.criterion=criterion;} public Double getScore(){return score;} public void setScore(Double score){this.score=score;} public String getComment(){return comment;} public void setComment(String comment){this.comment=comment;} }
